versions.variantCss:
.wemd-follow-bar[data-variant="bytedance-follow-bar"] {
  background: linear-gradient(135deg, var(--wemd-primary), var(--wemd-primary-dark));
  border-radius: var(--wemd-border-radius);
  padding: 16px 24px;
  margin: 16px 0;
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  box-shadow: var(--wemd-shadow);
}
.wemd-follow-bar[data-variant="bytedance-follow-bar"] .wemd-component-body {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  width: 100%;
  padding: 0;
}
.wemd-follow-bar[data-variant="bytedance-follow-bar"] .wemd-component-body .wemd-child-1 {
  color: #ffffff;
  font-size: 16px;
  font-weight: 700;
  margin: 0 auto 0 0;
}
.wemd-follow-bar[data-variant="bytedance-follow-bar"] .wemd-component-body .wemd-child-2 {
  display: inline-block;
  background: #ffffff;
  color: var(--wemd-primary);
  font-size: 14px;
  font-weight: 700;
  padding: 8px 24px;
  border-radius: 999px;
  margin: 0;
}
